INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (16, 1, 'theory', 'Quiz: your first program, types, and compilation');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 0, 'What does the linker do when building a C program?', '["Turns C into assembler", "Expands #include and #define", "Joins object files and libraries into an executable and fills in the addresses", "Optimizes the code"]', 2, 'The preprocessor expands directives, the compiler translates to assembler, the assembler produces an object file, and the linker puts everything together into one ELF.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 1, 'What are -7 / 2 and -7 % 2 in C?', '["-3 and -1", "-4 and 1", "-3 and 1", "-4 and -1"]', 0, 'Integer division drops the fractional part (toward zero), and the remainder takes the sign of the dividend, as in the processor; Python''s -4 and 1 is different.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 2, 'What happens with int x = INT_MAX; x = x + 1;?', '["x becomes INT_MIN", "The program crashes", "x stays equal to INT_MAX", "Undefined behavior: the standard defines no result"]', 3, 'Signed overflow is UB: the compiler may assume it never happens. Unsigned numbers, by contrast, wrap around modulo.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 3, 'What value does an uninitialized local variable int x; have?', '["Always 0", "Garbage: you must not read it", "NULL", "The minimum value of int"]', 1, 'Local variables are not zeroed; reading one is undefined behavior. Only global and static variables (.bss) get zeros by default.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (16, 1, 4, 'Why is the call printf("%d", 3.5) an error?', '["Because 3.5 is too long a number", "Because printf can''t print fractions", "The %d placeholder doesn''t match the double type: behavior is undefined", "It''s fine, the number will be rounded"]', 2, 'The compiler isn''t required to check that placeholder and argument match; a mismatch is UB. Turn on -Wall: it checks formats.');
